#!/usr/bin/env python3
"""Render or check the three assistant instruction files from one template."""

import argparse
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parent.parent
HEADER = (
    "<!-- Generated from docs/AGENT_INSTRUCTIONS.template.md; edit the template or profiles, then run\n"
    "     python3 tools/sync_agent_instructions.py --write. Do not edit this file directly. -->\n"
)
PROFILES = {
    "CLAUDE.md": {
        "assistant": "Claude",
        "scheduled": "Claude Cowork task every 6 h",
        "owner_session": "Claude Code",
        "delegation": "The session model plans and reviews; a subagent does the work. Claude only (GPT always uses Terra, Gemini always Flash): choose the subagent model per task: Haiku when the brief states exactly what to change and a mechanical check proves it (mechanical comment/doc edits, generators with tests, inventories); Sonnet for anything that needs reasoning (PORT, WIRE, trace analysis, capture scripts, audits, readability/comment meaning, owner 2026-11-11) and whenever unsure. A Haiku task that fails its check or review is redone on Sonnet.",
        "brief_tool": '(one per `Agent` call, `model: "haiku"` or `model: "sonnet"`; say which and why when launching)',
        "fix_tool": "(`SendMessage`)",
    },
    "GPT.md": {
        "assistant": "GPT",
        "scheduled": "GPT automation every 6 h",
        "owner_session": "Codex with GPT",
        "delegation": "Required models: GPT-6.1 Sol at high effort plans and reviews; GPT-6.1 Terra at medium effort writes code, always, for every kind of task (owner, 2026-11-11: the Haiku/Sonnet choice in CLAUDE.md is Claude-only).",
        "brief_tool": '(one per `spawn_agent` call, `model: "gpt-6.1-terra"`, `reasoning_effort: "medium"`, and `fork_turns: "none"`)',
        "fix_tool": "(`followup_task`)",
    },
    "GEMINI.md": {
        "assistant": "Gemini",
        "scheduled": "Gemini automation every 6 h",
        "owner_session": "Gemini",
        "delegation": "The Gemini session model plans and reviews; subagents always use Gemini Flash, for every kind of task, through the available native delegation tool (owner, 2026-11-11: the Haiku/Sonnet choice in CLAUDE.md is Claude-only).",
        "brief_tool": "(one per delegation call)",
        "fix_tool": "using the available native delegation tool",
    },
}
PLACEHOLDER = re.compile(r"\{\{([a-z_]+)\}\}")


def render(template, profile):
    def replace(match):
        return profile[match.group(1)]

    return HEADER + PLACEHOLDER.sub(replace, template)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true", help="write generated files")
    mode.add_argument("--check", action="store_true", help="check generated files (default)")
    parser.add_argument("--root", type=Path, default=ROOT, help="repository root")
    args = parser.parse_args()
    template = (args.root / "docs/AGENT_INSTRUCTIONS.template.md").read_text(encoding="utf-8")
    stale = []
    for filename, profile in PROFILES.items():
        target = args.root / filename
        expected = render(template, profile)
        if args.write:
            target.write_text(expected, encoding="utf-8")
        elif not target.is_file() or target.read_text(encoding="utf-8") != expected:
            stale.append(filename)
    if stale:
        print("Out-of-date assistant instructions: " + ", ".join(stale), file=sys.stderr)
        print("Run python3 tools/sync_agent_instructions.py --write", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
